<?php
declare(strict_types=1);
namespace App\Modules\Tourism\Models;
use App\Core\Database;
final class TourismDestination{private Database $db;public function __construct(){$this->db=app()->get('db');}public function all(int $t,bool $d=false):array{$w=$d?'deleted_at IS NOT NULL':'deleted_at IS NULL';return $this->db->fetchAll("SELECT d.*,(SELECT COUNT(*) FROM tourism_stays s WHERE s.tenant_id=d.tenant_id AND s.destination_id=d.id AND s.deleted_at IS NULL) stay_count FROM tourism_destinations d WHERE d.tenant_id=? AND d.{$w} ORDER BY d.id DESC",[$t]);}public function find(int $t,int $id):?array{return $this->one($t,$id,false);}public function findDeleted(int $t,int $id):?array{return $this->one($t,$id,true);}private function one(int $t,int $id,bool $d):?array{$w=$d?'deleted_at IS NOT NULL':'deleted_at IS NULL';return $this->db->fetch("SELECT * FROM tourism_destinations WHERE tenant_id=? AND id=? AND {$w} LIMIT 1",[$t,$id]);}public function create(int $t,array $d,int $u):int{$this->db->execute("INSERT INTO tourism_destinations(uuid,tenant_id,name,slug,description,district,city,state,best_time_to_visit,suggested_duration,latitude,longitude,status,created_by,updated_by) VALUES(UUID(),?,?,?,?,?,?,?,?,?,?,?,?,?,?)",[$t,$d['name'],$d['slug'],$d['description'],$d['district'],$d['city'],$d['state'],$d['best_time_to_visit'],$d['suggested_duration'],$d['latitude'],$d['longitude'],$d['status'],$u,$u]);return (int)$this->db->lastInsertId();}public function update(int $t,int $id,array $d,int $u):void{$this->db->execute("UPDATE tourism_destinations SET name=?,slug=?,description=?,district=?,city=?,state=?,best_time_to_visit=?,suggested_duration=?,latitude=?,longitude=?,status=?,updated_by=? WHERE tenant_id=? AND id=? AND deleted_at IS NULL",[$d['name'],$d['slug'],$d['description'],$d['district'],$d['city'],$d['state'],$d['best_time_to_visit'],$d['suggested_duration'],$d['latitude'],$d['longitude'],$d['status'],$u,$t,$id]);}public function softDelete(int $t,int $id,int $u):void{$this->db->execute("UPDATE tourism_destinations SET deleted_at=NOW(),updated_by=? WHERE tenant_id=? AND id=? AND deleted_at IS NULL",[$u,$t,$id]);}public function restore(int $t,int $id,int $u):void{$this->db->execute("UPDATE tourism_destinations SET deleted_at=NULL,updated_by=? WHERE tenant_id=? AND id=?",[$u,$t,$id]);}public function nameExists(int $t,string $n,?int $ignore=null):bool{$sql="SELECT id FROM tourism_destinations WHERE tenant_id=? AND name=? AND deleted_at IS NULL";$p=[$t,$n];if($ignore!==null){$sql.=" AND id<>?";$p[]=$ignore;}return $this->db->fetch($sql.' LIMIT 1',$p)!==null;}public function slugExists(int $t,string $s,?int $ignore=null):bool{$sql="SELECT id FROM tourism_destinations WHERE tenant_id=? AND slug=? AND deleted_at IS NULL";$p=[$t,$s];if($ignore!==null){$sql.=" AND id<>?";$p[]=$ignore;}return $this->db->fetch($sql.' LIMIT 1',$p)!==null;}}
